/**
 * Auto-generates lightweightChartsBundle.ts from node_modules.
 *
 * Runs as a postinstall hook so the WebView bundle always matches
 * the installed lightweight-charts version. This prevents silent
 * version drift that would break the chart months later.
 *
 * Usage:
 *   node scripts/bundle-lightweight-charts.js
 */

const fs = require('fs');
const path = require('path');

const SOURCE = path.resolve(
  __dirname,
  '..',
  'node_modules',
  'lightweight-charts',
  'dist',
  'lightweight-charts.standalone.production.js',
);

const TARGET = path.resolve(
  __dirname,
  '..',
  'src',
  'features',
  'chart',
  'rendering',
  'lightweightChartsBundle.ts',
);

if (!fs.existsSync(SOURCE)) {
  console.warn('[bundle-lightweight-charts] lightweight-charts not installed yet — skipping.');
  process.exit(0);
}

const src = fs.readFileSync(SOURCE, 'utf8');

// Extract the version from the source banner comment
const versionMatch = src.match(/Lightweight Charts[™]?\s+v([\d.]+)/);
const version = versionMatch ? versionMatch[1] : 'unknown';

// Append `true;` so injectedJavaScriptBeforeContentLoaded doesn't warn
const withTrue = src + '\ntrue;';
const escaped = JSON.stringify(withTrue);

const output = [
  `// Auto-generated by scripts/bundle-lightweight-charts.js — DO NOT EDIT`,
  `// Source: node_modules/lightweight-charts v${version}`,
  `// Regenerate: npm run bundle:charts`,
  `export const LIGHTWEIGHT_CHARTS_JS: string = ${escaped};`,
  '',
].join('\n');

// Only write if content actually changed (avoid triggering watchers on every install)
if (fs.existsSync(TARGET)) {
  const existing = fs.readFileSync(TARGET, 'utf8');
  if (existing === output) {
    console.log(`[bundle-lightweight-charts] v${version} — already up to date.`);
    process.exit(0);
  }
}

fs.writeFileSync(TARGET, output);
console.log(`[bundle-lightweight-charts] v${version} — bundled ${(src.length / 1024).toFixed(0)}KB → ${path.basename(TARGET)}`);
